INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10001, 'F0.1', 1001, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Governança corporativa de privacidade e segurança» (F0.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. A alta administração deve estabelecer, manter, monitorar e aprimorar o sistema de gestão
