INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10008, 'F0.8', 1001, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Governança corporativa de privacidade e segurança» (F0.8)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Instituir e implementar a Equipe de Prevenção, Tratamento e Resposta a Incidentes
Cibernéticos (ETIR), composta, preferencialmente, por profissional designadoes públicos civis ocupantes
de cargo efetivo ou militares, com capacitação técnica compatível com as atividades da
equipe. Para cada membro da Equipe deverá ser designado um substituto. Elaborar o
documento de constituição da ETIR conforme NC n° 05/IN01/DSIC/GSIPR, devidamente
aprovado pela alta administração da organização, para regulamentar o funcionamento da
equipe. [F0.8]', 'framework', 'F0.8') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10009, 'F0.9', 1002, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Políticas, programas e instrumentos de conformidade» (F0.9)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Instituir e implementar, preferencialmente em instância colegiada, o PGSI, documento que
contém, no mínimo, o disposto na IN GSI/PR nº 3/2021, art. 45, na forma de ações
estruturadas, políticas, normas e procedimentos para promover a segurança da informação
na organização. Recomenda-se que o PGSI contemple papéis e responsabilidades dos
agentes públicos envolvidos em sua execução, os prazos para realização das ações, além
da programação para implementação dos controles e medidas de segurança da informação
do Framework FPSI, e que especifique indicadores de desempenho, como o iSeg, a serem medi [F0.9]', 'framework', 'F0.9') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
