INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10011, 'F0.11', 1002, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Políticas, programas e instrumentos de conformidade» (F0.11)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Instituir e implementar uma Política de Segurança da Informação (POSIN), a partir da
formalização e aprovação por parte da autoridade máxima da instituição, com o objetivo de
estabelecer diretrizes, responsabilidades, competências e subsídios para a gestão da
segurança da informação. Revisar e atualizar a POSIN periodicamente ou quando ocorrerem
mudanças significativas na organização que possam impactar esta medida. [F0.11]', 'framework', 'F0.11') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10012, 'F0.12', 1002, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Políticas, programas e instrumentos de conformidade» (F0.12)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Instituir e implementar uma Política de Proteção de Dados Pessoais, que estabeleça as
diretrizes para o tratamento de dados pessoais, independentemente do meio em que são
tratados, incluindo papéis e responsabilidades dos agentes públicos envolvidos nos
tratamentos de dados pessoais. Instituir e divulgar demais políticas, normas e procedimentos
sobre a temática. Revisar e atualizar os documentos periodicamente ou quando ocorrerem
mudanças significativas na organização que possam impactar esta medida. [F0.12]', 'framework', 'F0.12') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10013, 'F0.13', 1002, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Políticas, programas e instrumentos de conformidade» (F0.13)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter, em conformidade ao Capítulo III da IN GSI/PR nº 3/2021, um
processo de gestão de riscos de segurança da informação alinhado com o modelo de gestão
de riscos institucional, compatível com a missão e os objetivos estratégicos da organização
considerando o disposto nos incisos do art. 11. Além disso, o processo deve ser composto
por, no mínimo: plano de gestão de riscos de segurança da informação, conforme disposto
no art. 13; relatório de identificação, análise e avaliação dos riscos de segurança da
informação, conforme disposto no art. 14; e, relatório de tratamento de ris [F0.13]', 'framework', 'F0.13') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10014, 'F0.14', 1002, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Políticas, programas e instrumentos de conformidade» (F0.14)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. 19
Guia do Framework de Privacidade e Segurança da Informação (Framework FPSI 2.0)
Estabelecer e manter, em conformidade ao Capítulo IV da IN GSI/PR nº 3/2021, um
processo de gestão de continuidade de negócios em segurança da informação baseado nas
estratégias de continuidade para as atividades críticas, na avaliação dos riscos levantados
no processo de gestão de riscos e nas diretrizes institucionais sobre gestão de continuidade
de negócio. Tal processo deve ser composto por um plano de continuidade de negócios em
