INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10030, 'F3.1', 1005, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção de dados em repouso e em trânsito» (F3.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de gestão de dados. No processo, tratar a criticidade, o
