INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10039, 'F3.10', 1005, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção de dados em repouso e em trânsito» (F3.10)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Criptografar os dados críticos para a organização que estão em trânsito, considerando a NC
nº 09/IN01/DSIC/GSIPR. [F3.10]', 'framework', 'F3.10') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10040, 'F3.11', 1005, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção de dados em repouso e em trânsito» (F3.11)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Criptografar os dados críticos para a organização e que estão em repouso nos profissional designadoes,
sistemas e banco de dados que os armazenam, considerando a NC nº
09/IN01/DSIC/GSIPR. [F3.11]', 'framework', 'F3.11') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10041, 'F3.12', 1005, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção de dados em repouso e em trânsito» (F3.12)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Segmentar o processamento e armazenamento de dados com base na sua criticidade. Não
processar dados críticos para a organização em ativos institucionais destinados a dados de
menor criticidade. [F3.12]', 'framework', 'F3.12') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10042, 'F3.13', 1005, NULL, 'GI3', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção de dados em repouso e em trânsito» (F3.13)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Implementar uma ferramenta automatizada, como uma solução de prevenção de perda de
dados (Data Loss Prevention, DLP) baseada em host, para identificar todos os dados críticos
processados, transmitidos ou armazenados por meio dos ativos institucionais. [F3.13]', 'framework', 'F3.13') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10043, 'F3.14', 1005, NULL, 'GI3', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção de dados em repouso e em trânsito» (F3.14)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Registrar o acesso aos dados críticos para a organização, incluindo modificação e descarte. [F3.14]', 'framework', 'F3.14') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10044, 'F4.1', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de configuração segura para os ativos institucionais
(dispositivos de usuário final, incluindo portáteis e móveis, dispositivos da IOT e não
computacionais, profissional designadoes) e soluções de software. Revisar e atualizar a documentação
anualmente ou quando ocorrerem mudanças significativas na organização que possam
impactar esta medida. [F4.1]', 'framework', 'F4.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10045, 'F4.2', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de configuração segura para dispositivos de rede.
Revisar e atualizar a documentação anualmente ou quando ocorrerem mudanças
significativas na organização que possam impactar esta medida. [F4.2]', 'framework', 'F4.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10046, 'F4.3', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Configurar o bloqueio automático de sessão, quando aplicável, nos ativos institucionais após
um período definido de inatividade. [F4.3]', 'framework', 'F4.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10047, 'F4.4', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Implementar e gerenciar um firewall nos profissional designadoes, quando suportado. [F4.4]', 'framework', 'F4.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10048, 'F4.5', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Implementar e gerenciar um firewall baseado em host ou uma ferramenta de filtragem de
porta nos dispositivos de usuário final, com uma regra de negação padrão que bloqueia todo
o tráfego, exceto os serviços e portas que são explicitamente permitidos. [F4.5]', 'framework', 'F4.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10049, 'F4.6', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.6)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Gerenciar com segurança os ativos institucionais e soluções de software. Exemplos de
implementações incluem gestão de configuração por meio de infraestrutura como código
com controle de versão (version controlled-infrastructure-as-code) e acesso a interfaces
administrativas por meio de protocolos de rede seguros. [F4.6]', 'framework', 'F4.6') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10050, 'F4.7', 1006, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.7)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Gerenciar contas padrão nos ativos institucionais e soluções de software, como root,
administrador e outras contas de fornecedores pré-configuradas. [F4.7]', 'framework', 'F4.7') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10051, 'F4.8', 1006, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.8)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Desinstalar ou desativar serviços desnecessários nos ativos institucionais e soluções de
software, como serviço de compartilhamento de arquivo não utilizado, módulo de aplicação
web ou função de serviço. [F4.8]', 'framework', 'F4.8') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10052, 'F4.9', 1006, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.9)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Configurar profissional designadoes DNS confiáveis nos ativos institucionais. Exemplos de implementações
incluem configurar a infraestrutura de rede para usar profissional designadoes DNS controlados pela
organização ou profissional designadoes DNS externos confiáveis. [F4.9]', 'framework', 'F4.9') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10053, 'F4.10', 1006, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.10)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Aplicar o bloqueio automático dos dispositivos portáteis de usuário final após um número de
tentativas de autenticação com falha, com base no limite definido pela organização. [F4.10]', 'framework', 'F4.10') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10054, 'F4.11', 1006, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.11)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Assegurar que os dispositivos portáteis de usuário final de propriedade da organização
estejam preparados para limpeza remota e executá-la conforme previsto na política de
gestão de ativos institucionais, incluindo casos como dispositivos perdidos ou roubados, ou
quando um indivíduo não trabalha mais na organização. [F4.11]', 'framework', 'F4.11') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10055, 'F4.12', 1006, NULL, 'GI3', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Configuração segura e hardening» (F4.12)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Certificar de que a separação de espaços de trabalho seja usada nos dispositivos móveis de
usuário final, ou seja, separar aplicações e dados institucionais de aplicações e dados de
uso pessoal nos dispositivos, quando suportado. [F4.12]', 'framework', 'F4.12') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10056, 'F5.1', 1007, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de contas e identidades» (F5.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um inventário de todas as contas gerenciadas na organização. O
inventário deve incluir contas de usuário e de administrador, e conter minimamente o nome
do colaborador, o nome do usuário, datas de início e término, além do departamento.
Validar se todas as contas ativas estão autorizadas, trimestralmente ou em intervalos
menores. [F5.1]', 'framework', 'F5.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10057, 'F5.2', 1007, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de contas e identidades» (F5.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Configurar os ativos institucionais para evitar ou desestimular a reutilização de senhas,
promovendo a adoção de senhas únicas para ativos diferentes. [F5.2]', 'framework', 'F5.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10058, 'F5.3', 1007, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de contas e identidades» (F5.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Desabilitar ou excluir quaisquer contas inativas, conforme política de gestão de contas, após
um período de inatividade estabelecido pela organização. [F5.3]', 'framework', 'F5.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10059, 'F5.4', 1007, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de contas e identidades» (F5.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. 35
Guia do Framework de Privacidade e Segurança da Informação (Framework FPSI 2.0)
Limitar os privilégios de administrador às contas de administrador dedicadas. Realizar
atividades gerais de computação, como navegação na Internet, e-mail e uso do pacote de
produtividade, a partir da conta primária não privilegiada do usuário. [F5.4]', 'framework', 'F5.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10060, 'F5.5', 1007, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de contas e identidades» (F5.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um inventário de contas de serviço. O inventário, no mínimo, deve
conter a unidade proprietária, data de revisão e propósito. Realizar revisões de contas de
serviço para validar se todas as contas ativas estão autorizadas, em uma programação
recorrente, no mínimo trimestralmente ou em intervalos menores. [F5.5]', 'framework', 'F5.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10061, 'F5.6', 1007, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de contas e identidades» (F5.6)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Centralizar a gestão de contas por meio de serviço de diretório ou de identidade. [F5.6]', 'framework', 'F5.6') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10062, 'F6.1', 1008, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo, de preferência automatizado, para conceder acesso
físico e lógico aos ativos institucionais e soluções de software mediante novo ingresso de
colaborador, concessão de direitos ou mudança de função de um usuário. [F6.1]', 'framework', 'F6.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10063, 'F6.2', 1008, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo, de preferência automatizado, para revogar o acesso aos
ativos institucionais e soluções de software, por meio da desativação de contas
imediatamente após seu encerramento, revogação de direitos ou mudança de função de um
usuário. Desativar contas, em vez de excluí-las, pode ser necessário para preservar as
trilhas de auditoria. [F6.2]', 'framework', 'F6.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10064, 'F6.3', 1008, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Exigir que todas as soluções de software da organização ou de terceiros expostas
externamente apliquem autenticação multifator, onde suportado. Aplicar autenticação
multifator por meio de um serviço de diretório ou provedor de Single Sign-On (SSO) é uma
forma de implementação desta medida. [F6.3]', 'framework', 'F6.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10065, 'F6.4', 1008, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Exigir autenticação multifator para acesso remoto à rede. [F6.4]', 'framework', 'F6.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10066, 'F6.5', 1008, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Exigir autenticação multifator para todas as contas de acesso administrativo, em todos os
ativos institucionais e soluções de software, sejam gerenciados no site local ou por meio de
um provedor terceirizado. [F6.5]', 'framework', 'F6.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10067, 'F6.6', 1008, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.6)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um inventário dos sistemas de autenticação e autorização da
organização, incluindo aqueles hospedados no site local ou em um provedor de serviços
remoto. Revisar e atualizar o inventário semestralmente ou em intervalos menores. [F6.6]', 'framework', 'F6.6') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10068, 'F6.7', 1008, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.7)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Centralizar o controle de acesso para todos os ativos institucionais e soluções de software
por meio de um serviço de diretório ou provedor de Single Sign-On (SSO), quando
suportado. [F6.7]', 'framework', 'F6.7') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10069, 'F6.8', 1008, NULL, 'GI3', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Controle de acesso e segregação de funções» (F6.8)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Definir e manter o controle de acesso baseado em funções, determinando e documentando
os direitos de acesso necessários para cada função dentro da organização para cumprir com
sucesso as funções atribuídas. Revisar os controles de acesso para validar se todos os
privilégios estão autorizados, em uma programação recorrente, uma vez por ano ou em
intervalos menores. [F6.8]', 'framework', 'F6.8') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10070, 'F7.1', 1009, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de gestão de vulnerabilidade para ativos institucionais e
soluções de software. Revisar e atualizar a documentação anualmente ou quando ocorrerem
mudanças significativas na organização que possam impactar esta medida. [F7.1]', 'framework', 'F7.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10071, 'F7.2', 1009, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de remediação, fundamentado na estratégia de
remediação institucional baseada em risco, com revisões semestrais ou em intervalos
menores. [F7.2]', 'framework', 'F7.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10072, 'F7.3', 1009, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Realizar atualizações do sistema operacional por meio da gestão automatizada de
atualizações, mensalmente ou com mais frequência. [F7.3]', 'framework', 'F7.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10073, 'F7.4', 1009, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Realizar atualizações de aplicações por meio da gestão automatizada de atualizações,
mensalmente ou em intervalos menores. [F7.4]', 'framework', 'F7.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10074, 'F7.5', 1009, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Realizar varreduras automatizadas de vulnerabilidade em ativos institucionais e soluções de
software internos, trimestralmente ou em intervalos menores. Realizar varreduras
autenticadas e não autenticadas. [F7.5]', 'framework', 'F7.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10075, 'F7.6', 1009, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.6)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Executar varreduras de vulnerabilidade automatizadas nos ativos institucionais e soluções
de software expostos externamente. Executar varreduras mensalmente ou em intervalos
menores. [F7.6]', 'framework', 'F7.6') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10076, 'F7.7', 1009, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Gestão de vulnerabilidades e patches» (F7.7)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Corrigir as vulnerabilidades detectadas por meio de processos e ferramentas, mensalmente
ou em intervalos menores, com base no processo de remediação. [F7.7]', 'framework', 'F7.7') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10077, 'F8.1', 1010, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de gestão de logs de auditoria que defina os requisitos
de registro de logs da organização, considerando a NC nº 21/IN01/DSIC/GSIPR. No mínimo,
abordar a coleta, revisão e armazenamento dos logs de auditoria para os ativos institucionais
e soluções de software, considerando o tempo de retenção e os dados estritamente
necessários à segurança da informação. Revisar e atualizar a documentação anualmente ou
sempre que ocorrerem mudanças significativas na organização que possam impactar esta
medida. [F8.1]', 'framework', 'F8.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10078, 'F8.2', 1010, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Coletar logs de auditoria. Certificar-se de que o log, de acordo com o processo de gestão de
log de auditoria da organização, tenha sido habilitado em todos os ativos institucionais e
soluções de software em que esta funcionalidade estiver disponível. [F8.2]', 'framework', 'F8.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10079, 'F8.3', 1010, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Assegurar que os logs possuam armazenamento seguro em conformidade com normas
internas e regulatórias, preservando sua integridade e proteção contra alterações. Além
disso, garantir acessibilidade e monitoramento contínuo, assegurando a disponibilidade dos
logs para auditorias e investigações, bem como a aderência aos normativos aplicáveis, em
atendimento aos requisitos de gerenciamento de registros de auditoria da organização. [F8.3]', 'framework', 'F8.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10080, 'F8.4', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Padronizar a sincronização de tempo. Configurar todos os ativos institucionais e soluções de
software com pelo menos duas fontes de sincronização de tempo, quando suportado. [F8.4]', 'framework', 'F8.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10081, 'F8.5', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. 42
Guia do Framework de Privacidade e Segurança da Informação (Framework FPSI 2.0)
Configurar o log de auditoria detalhado para os ativos institucionais e soluções de software
que contenham dados críticos para a organização. Incluir a origem do evento, data, nome de
usuário, carimbo de data e hora, endereços de origem, endereços de destino e outros
elementos úteis que possam ajudar em uma investigação forense. [F8.5]', 'framework', 'F8.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10082, 'F8.6', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.6)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Habilitar o registro de log de consulta do profissional designado DNS inclusive para detectar pesquisas de
nomes de host para domínios maliciosos conhecidos, quando suportado. [F8.6]', 'framework', 'F8.6') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10083, 'F8.7', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.7)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Coletar logs de auditoria de requisição de URL em ativos institucionais, quando suportado. [F8.7]', 'framework', 'F8.7') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10084, 'F8.8', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.8)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Habilitar o log de auditoria sobre ferramentas de linha de comando, tais como Microsoft
Powershell, Bash e demais terminais administrativos remotos. [F8.8]', 'framework', 'F8.8') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10085, 'F8.9', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.9)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Centralizar, sempre que possível, a coleta e retenção de logs de auditoria de acordo com um
processo de gerenciamento de logs de auditoria. [F8.9]', 'framework', 'F8.9') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10086, 'F8.10', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.10)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Garantir a retenção dos logs de auditoria pelo período estabelecido pela organização. [F8.10]', 'framework', 'F8.10') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10087, 'F8.11', 1010, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.11)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Realizar análises de logs de auditoria para detectar anomalias ou eventos anormais que
possam indicar uma ameaça potencial. Realizar revisões semanalmente ou em intervalos
menores. [F8.11]', 'framework', 'F8.11') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10088, 'F8.12', 1010, NULL, 'GI3', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Registros, logs e trilha de auditoria» (F8.12)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. 43
Guia do Framework de Privacidade e Segurança da Informação (Framework FPSI 2.0)
Coletar logs de provedores de serviços, quando suportado. Exemplos de implementações
incluem coleta de eventos de autenticação e autorização, eventos de criação e de descarte
de dados e eventos de gestão de usuários. [F8.12]', 'framework', 'F8.12') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10089, 'F9.1', 1011, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «E-mail, navegadores e colaboração segura» (F9.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Assegurar que apenas navegadores e clientes de e-mail totalmente suportados por seus
fornecedores tenham permissão para executar na organização, usando apenas a versão
mais recente. [F9.1]', 'framework', 'F9.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10090, 'F9.2', 1011, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «E-mail, navegadores e colaboração segura» (F9.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Usar serviços de filtragem de DNS em todos os dispositivos do usuário final, incluindo ativos
remotos e locais, para bloquear o acesso a domínios maliciosos conhecidos. [F9.2]', 'framework', 'F9.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10091, 'F9.3', 1011, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «E-mail, navegadores e colaboração segura» (F9.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Aplicar e atualizar filtros de URL baseados em rede para limitar os ativos institucionais de se
