INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10102, 'F10.7', 1012, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Proteção contra malware e phishing» (F10.7)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Utilizar software antimalware baseado em comportamento. [F10.7]', 'framework', 'F10.7') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10103, 'F11.1', 1013, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Backup, continuidade e recuperação» (F11.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter um processo de realização de cópias de segurança (backups),
incluindo as atividades de recuperação de dados. Tal processo deve descrever em seu
escopo critérios de priorização para recuperação, bem como medidas para segurança dos
dados. Periodicamente, deve ser realizada uma revisão ou atualização deste processo,
48
Guia do Framework de Privacidade e Segurança da Informação (Framework FPSI 2.0)
assim como em casos específicos quando ocorrerem mudanças significativas que venham a
impactar esta medida. [F11.1]', 'framework', 'F11.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10104, 'F11.2', 1013, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Backup, continuidade e recuperação» (F11.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter procedimentos para que todos os dados dos ativos institucionais
tenham cópias de segurança (backups) realizadas automaticamente e de forma regular, de
acordo com a criticidade dos dados. [F11.2]', 'framework', 'F11.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10105, 'F11.3', 1013, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Backup, continuidade e recuperação» (F11.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter procedimentos para proteger os dados de recuperação com controles
equivalentes aos dos dados originais. Considerar o uso de criptografia ou separação de
dados, conforme os requisitos. [F11.3]', 'framework', 'F11.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10106, 'F11.4', 1013, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Backup, continuidade e recuperação» (F11.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Criar e manter pelo menos uma instância isolada dos dados de recuperação. Alguns
exemplos deste tipo de implementação são o controle de versão de destinos de backup por
meio de sistemas ou serviços off-line (backup off-line, não acessível por meio de uma
conexão de rede), em nuvem, ou em datacenter separado do site local. [F11.4]', 'framework', 'F11.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10107, 'F11.5', 1013, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Backup, continuidade e recuperação» (F11.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Realizar o teste de integridade do backup regularmente, executando um processo de
restauração de dados para assegurar que o backup esteja funcionando corretamente
conforme política de backup. [F11.5]', 'framework', 'F11.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10108, 'F12.1', 1014, NULL, 'GI1', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter procedimentos para assegurar que a infraestrutura de rede da
organização esteja sempre atualizada. Revisar as versões de software mensalmente, ou
50
Guia do Framework de Privacidade e Segurança da Informação (Framework FPSI 2.0)
com maior frequência, para verificar se ainda estão sendo suportados pelos seus
fornecedores. [F12.1]', 'framework', 'F12.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10109, 'F12.2', 1014, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Projetar e manter uma arquitetura de rede segura abordando, no mínimo, segmentação,
privilégio mínimo e disponibilidade. Exemplos de implementações incluem documentação,
políticas e componentes de projeto. [F12.2]', 'framework', 'F12.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10110, 'F12.3', 1014, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Gerenciar com segurança a infraestrutura de rede da organização. Exemplos de
implementações incluem a Infraestrutura como Código (Infrastructure as Code, IaC) com
controle de versão e o uso de protocolos de rede seguros. [F12.3]', 'framework', 'F12.3') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10111, 'F12.4', 1014, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.4)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Elaborar e manter diagramas e demais documentações da arquitetura de rede da
organização. Revisar e atualizar as documentações anualmente ou quando ocorrerem
mudanças significativas que possam impactar esta medida. [F12.4]', 'framework', 'F12.4') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10112, 'F12.5', 1014, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.5)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Centralizar a autenticação, autorização e auditoria da rede. [F12.5]', 'framework', 'F12.5') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10113, 'F12.6', 1014, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.6)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Adotar protocolos de comunicação e gerenciamento de rede seguros. [F12.6]', 'framework', 'F12.6') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10114, 'F12.7', 1014, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.7)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. GI2
Exigir que os usuários que acessam a rede de forma remota utilizem uma VPN gerenciada
pela organização e realizem autenticação via serviços AAA antes de qualquer acesso. [F12.7]', 'framework', 'F12.7') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10115, 'F12.8', 1014, NULL, 'GI3', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Redes, segmentação e conectividade» (F12.8)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Estabelecer e manter recursos de computação dedicados, física ou logicamente separados,
para todas as tarefas administrativas de TI ou tarefas que exijam acesso administrativo. Os
recursos de computação devem ser segmentados da rede primária da organização e não
devem ter acesso à internet. [F12.8]', 'framework', 'F12.8') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10116, 'F13.1', 1015, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Monitoramento e detecção de ameaças» (F13.1)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Centralizar os alertas de eventos de segurança dos ativos institucionais e soluções de
software da organização para correlação e análise de registros. As boas práticas demandam
o uso de um Security Information and Event Management (SIEM), que inclui alertas de
correlação de eventos definidos pelo fornecedor. Uma plataforma de análise de log
configurada com aletas de correlação relevantes para a segurança também atende esta
medida. [F13.1]', 'framework', 'F13.1') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10117, 'F13.2', 1015, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Monitoramento e detecção de ameaças» (F13.2)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Implantar soluções para detecção de intrusão baseada em host nos ativos institucionais,
quando apropriado ou suportado. [F13.2]', 'framework', 'F13.2') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10118, 'F13.3', 1015, NULL, 'GI2', NULL, 'A organização comprova, com evidências atualizadas, o requisito «Monitoramento e detecção de ameaças» (F13.3)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Implantar soluções para detecção de intrusão de rede nos ativos institucionais, quando
apropriado. Exemplos de implementações incluem o uso de um Network Intrusion Detection
System (NIDS) ou serviço de provedor de nuvem equivalente.
