INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10208, 'F25.8', 1027, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Princípios e accountability (LGPD)» (F25.8)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Para cada uma das operações de tratamento de dados pessoais registrada em decorrência
do Controle 19, a organização deve implementar mecanismos de mitigação de riscos e
medidas que previnam a ocorrência de danos no tratamento de dados pessoais (também em
razão da medida 0.17). Para os tratamentos que possam gerar riscos às liberdades civis e
aos direitos fundamentais, elaborar relatórios de impactos à proteção de dados pessoais
(RIPD), igualmente em atendimento à medida 23.3. Estabelecer procedimento ou
metodologia para assegurar a privacidade desde a fase de concepção do produto ou do
serviço [F25.8]', 'framework', 'F25.8') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
