INSERT INTO public.medida (id, id_medida, id_controle, id_cisv8, grupo_imple, funcao_nist_csf, medida, descricao, pack_id, codigo_origem) VALUES (10210, 'F25.10', 1027, NULL, NULL, NULL, 'A organização comprova, com evidências atualizadas, o requisito «Princípios e accountability (LGPD)» (F25.10)?', 'Para empresas e organizações privadas, a FPSI recomenda documentar evidências, responsáveis e revisões periódicas. Garantir que todas as medidas implementadas com o objetivo de assegurar a conformidade
às normas de proteção de dados pessoais sejam devidamente evidenciadas, de forma
sistemática e auditável, registrando inclusive a eficácia das medidas. Isto inclui o registro de
evidências tais como: o PGP; o registro das operações de tratamento e as respectivas ações
para conformidade; as solicitações formuladas pelos agentes públicos ao encarregado e
suas respectivas orientações; o atendimento aos direitos dos titulares; os RIPDs; as ações
de conscientização e de treinamento; o relatório anual contemplando [F25.10]', 'framework', 'F25.10') ON CONFLICT (id) DO UPDATE SET medida = EXCLUDED.medida, descricao = EXCLUDED.descricao, pack_id = EXCLUDED.pack_id, codigo_origem = EXCLUDED.codigo_origem;
